var reason = ZT.getVariableValue("decline_reason", "");
var key = "";
if (reason === "Fraud") key = "fraud";
else if (reason === "Authentication") key = "authentication";
else if (reason === "Not Enough Balance") key = "not_enough_balance";
else if (reason === "CVC Declines") key = "cvc";
else if (reason === "Integration Issues") key = "integration";
else if (reason === "Other Generic Declines") key = "other_generic";
else if (reason === "Card-Related Issues") {
    key = (ZT.getVariableValue("au_nto", "") === "Yes") ? "au_nto_enabled" : "au_nto_not_enabled";
} else if (reason === "No Specific Acquirer Response") {
    key = (ZT.getVariableValue("no_specific_product", "") === "Yes") ? "product_feedback" : "escalate_po";
}
ZT.setFormData("outcome_key", key);
